 public static function related_index(WP_REST_Request $r){$p=self::resolve_project($r);if(is_wp_error($p))return$p;$e=sanitize_key((string)$r['entity']);$t=self::RELATED[$e]??'';if(''===$t)return self::not_found(__('Related entity not found.','projectpress'));return self::success(DBHelper::get_all($t,array('project_id'=>$p->get_id()),'*','settings'===$e?'updated_at DESC':'created_at DESC'));} public static function related_create(WP_REST_Request $r){$p=self::resolve_project($r);if(is_wp_error($p))return$p;$e=sanitize_key((string)$r['entity']);if('activity'===$e)return new WP_Error('projectpress_rest_activity_read_only',__('Activity is read only.','projectpress'),array('status'=>405));$d=self::related_input($e,$p->get_id(),$r);if(is_wp_error($d))return$d;$id=DBHelper::insert(self::RELATED[$e],$d);return false===$id?new WP_Error('projectpress_rest_create_failed',__('The related record could not be created.','projectpress'),array('status'=>500)):self::success(DBHelper::get_by_id(self::RELATED[$e],(int)$id),201);} public static function related_delete(WP_REST_Request $r){$p=self::resolve_project($r);if(is_wp_error($p))return$p;$e=sanitize_key((string)$r['entity']);$t=self::RELATED[$e]??'';$id=absint($r['id']);$row=$t?DBHelper::get_by_id($t,$id):null;if(!$row||(int)$row['project_id']!==$p->get_id())return self::not_found(__('Related record not found.','projectpress'));return DBHelper::delete($t,array('id'=>$id))?self::success(array('deleted'=>true,'id'=>$id)):new WP_Error('projectpress_rest_delete_failed',__('The related record could not be deleted.','projectpress'),array('status'=>500));}
