 private static function related_input(string $e,int $pid,WP_REST_Request $r){$now=current_time('mysql',true);if('files'===$e){$a=absint($r->get_param('attachment_id'));if('attachment'!==get_post_type($a))return new WP_Error('projectpress_rest_file_invalid',__('A valid media attachment is required.','projectpress'),array('status'=>400));return array('project_id'=>$pid,'attachment_id'=>$a,'file_label'=>sanitize_text_field((string)$r->get_param('label')),'created_by'=>get_current_user_id(),'created_at'=>$now);}if('settings'===$e){$k=sanitize_key((string)$r->get_param('key'));if(''===$k)return new WP_Error('projectpress_rest_setting_key_required',__('A setting key is required.','projectpress'),array('status'=>400));return array('project_id'=>$pid,'setting_key'=>$k,'setting_value'=>sanitize_textarea_field((string)$r->get_param('value')),'updated_by'=>get_current_user_id(),'updated_at'=>$now);}if(!in_array($e,array('milestones','discussions','notes'),true))return self::not_found(__('Related entity not found.','projectpress'));$title=sanitize_text_field((string)$r->get_param('title'));if(''===$title)return new WP_Error('projectpress_rest_title_required',__('A title is required.','projectpress'),array('status'=>400));$d=array('project_id'=>$pid,'title'=>$title,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if('milestones'===$e){$d['description']=sanitize_textarea_field((string)$r->get_param('description'));$d['status']='planned';$target=sanitize_text_field((string)$r->get_param('target_date'));if(''!==$target&&false===strtotime($target))return new WP_Error('projectpress_rest_date_invalid',__('The target date is invalid.','projectpress'),array('status'=>400));$d['target_date']=''===$target?null:gmdate('Y-m-d H:i:s',strtotime($target));}else{$d['content']=sanitize_textarea_field((string)$r->get_param('content'));$d['status']='open';}return$d;}
 private static function resolve_project(WP_REST_Request $r){$id=sanitize_text_field((string)$r->get_param('project'));if(''===$id)return new WP_Error('projectpress_rest_project_required',__('A project identifier is required.','projectpress'),array('status'=>400));$x=self::projects()->resolve($id);if(is_wp_error($x)&&!isset($x->error_data[$x->get_error_code()]))$x->add_data(array('status'=>404),$x->get_error_code());return$x;} private static function project_data(Project $p):array{return$p->to_array();} private static function success($data,int $status=200,array $meta=array()):WP_REST_Response{$body=array('success'=>true,'data'=>$data);if($meta)$body['meta']=$meta;return new WP_REST_Response($body,$status);} private static function domain_response($x,int $status=200){return is_wp_error($x)?$x:self::success(is_object($x)&&method_exists($x,'to_array')?$x->to_array():$x,$status);} private static function forbidden():WP_Error{return new WP_Error('projectpress_rest_forbidden',__('You do not have permission to perform this action.','projectpress'),array('status'=>rest_authorization_required_code()));} private static function not_found(string $m):WP_Error{return new WP_Error('projectpress_rest_not_found',$m,array('status'=>404));} private static function projects():ProjectManager{return self::$projects??=ProjectManager::get_instance();} private static function permissions():ProjectPermissions{return self::$permissions??=new ProjectPermissions();}
 public static function validate_licence(WP_REST_Request $r):WP_REST_Response|WP_Error{$token=sanitize_text_field((string)$r->get_param('token'));$product=sanitize_key((string)$r->get_param('product_id'));$site=esc_url_raw((string)$r->get_param('site_url'));if(''===$token||''===$product)return new WP_Error('invalid_request','A licence token and product id are required.',array('status'=>400));$valid=LicenceManager::validate_license($token,$product,''!==$site?$site:null);return new WP_REST_Response(array('valid'=>$valid,'token'=>$token,'product_id'=>$product),$valid?200:400);}
